/* ------------------------------------------------------------------ */
/*  Mini-Game Builder Helper for Data Science                          */
/* ------------------------------------------------------------------ */

function buildDataScienceMiniGame(spec: DataScienceDaySpec): MiniGameConfig {
  const diff = spec.day <= 15 ? 1 : spec.day <= 30 ? 2 : spec.day <= 60 ? 3 : spec.day <= 75 ? 4 : 5;

  if (spec.gameKind === "match") {
    return matchGame(
      spec.gameType,
      spec.gameTitle,
      `Match each Data Science concept to its correct role for: ${spec.title}.`,
      diff,
      [
        { left: spec.pipelineNodes[0]?.[1] ?? "Concept A", right: spec.pipelineNodes[0]?.[2] ?? "Role A" },
        { left: spec.pipelineNodes[1]?.[1] ?? "Concept B", right: spec.pipelineNodes[1]?.[2] ?? "Role B" },
        { left: spec.pipelineNodes[2]?.[1] ?? "Concept C", right: spec.pipelineNodes[2]?.[2] ?? "Role C" },
        { left: spec.pipelineNodes[3]?.[1] ?? "Concept D", right: spec.pipelineNodes[3]?.[2] ?? "Role D" },
      ],
    );
  }

  if (spec.gameKind === "predict") {
    return predictGame(
      spec.gameType,
      spec.gameTitle,
      `# Data Science Simulation - Day ${spec.day}\n# Topic: ${spec.title}\nimport numpy as np\noutput = "${spec.pipelineNodes[0]?.[1]} -> ${spec.pipelineNodes[3]?.[1]}"\nprint(output)`,
      [
        spec.mcqCorrect,
        spec.mcqWrong[0] ?? "Option A",
        spec.mcqWrong[1] ?? "Option B",
        spec.mcqWrong[2] ?? "Option C",
      ],
      0,
      spec.mcqExpl,
      diff,
    );
  }

  if (spec.gameKind === "arrange") {
    return arrangeGame(
      spec.gameType,
      spec.gameTitle,
      `Arrange the data science pipeline stages in correct execution sequence for: ${spec.title}.`,
      spec.pipelineNodes.map((n, idx) => ({
        id: `ds-block-${idx + 1}`,
        code: `${idx + 1}. ${n[1]} (${n[2]})`,
        order: idx + 1,
      })),
      diff,
    );
  }

  if (spec.gameKind === "error") {
    return errorGame(
      spec.gameType,
      spec.gameTitle,
      `# Data Science Code Inspection - Day ${spec.day}\n# ${spec.title}\ndef analyze_data(df):\n    # Defect condition on Day ${spec.day}\n    raise ValueError("Statistical data integrity defect detected")`,
      [
        { line: 5, description: "Unvalidated feature transformation causing data leakage or collinearity" },
        { line: 3, description: "Missing type checks and outlier rejection boundary" },
      ],
      diff,
    );
  }

  if (spec.gameKind === "pipeline") {
    return pipelineGame(
      spec.gameType,
      spec.gameTitle,
      `Assemble the analytics architecture pipeline stages in correct execution sequence for ${spec.title}.`,
      spec.pipelineNodes.map((n) => n[1]),
      [0, 1, 2, 3],
      diff,
    );
  }

  return fillBlanksGame(
    spec.gameType,
    spec.gameTitle,
    `In data science, ${spec.pipelineNodes[0]?.[1] ?? "input"} transforms via ${spec.pipelineNodes[1]?.[1] ?? "method"} to produce ${spec.pipelineNodes[3]?.[1] ?? "metric"}.`,
    [
      {
        placeholder: spec.pipelineNodes[0]?.[1] ?? "input",
        answer: spec.pipelineNodes[0]?.[1] ?? "input",
        options: [spec.pipelineNodes[0]?.[1] ?? "input", "StaticMean", "RandomNoise"],
      },
    ],
    diff,
  );
}

/* ------------------------------------------------------------------ */
/*  Assemble All 90 Data Science Lessons                               */
/* ------------------------------------------------------------------ */

export function buildDataScienceCurriculum(): CourseCurriculum {
  const curriculum: CourseCurriculum = {};

  for (const spec of DATASCIENCE_DAYS) {
    const isProjectDay = spec.day >= 76;
    const projectConfig = isProjectDay
      ? {
          projectTitle: "Enterprise Predictive Customer Lifetime Value & Algorithmic Churn Engine",
          overview: "Architect and build an end-to-end customer analytics and predictive intelligence engine combining DuckDB Parquet data lakehouse ingestion, sliding-window RFM feature engineering, XGBoost/LightGBM classification and regression, TreeSHAP explainability, and containerized FastAPI real-time serving with Redis.",
          techStack: ["Python", "Pandas", "DuckDB", "XGBoost", "LightGBM", "SHAP", "Feast", "Redis", "FastAPI", "Docker", "Streamlit"],
          milestone: {
            day: spec.day,
            title: spec.title,
            deliverable: `Production Deliverable for Day ${spec.day}: ${spec.description}`,
            acceptanceCriteria: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
          },
          evaluationRubric: [
            { criteria: "Statistical Rigor & Data Quality", weight: 30 },
            { criteria: "Model Accuracy & PR-AUC Optimization", weight: 30 },
            { criteria: "SHAP Explainability & Causal Insights", weight: 20 },
            { criteria: "Production Serving & Feature Store Architecture", weight: 20 },
          ],
        }
      : undefined;

    curriculum[spec.day] = buildLesson("datascience", {
      day: spec.day,
      title: spec.title,
      description: spec.description,
      learningObjectives: [spec.objectives[0], spec.objectives[1], spec.objectives[2]],
      animationPipeline: pipeline("datascience", ...spec.pipelineNodes),
      miniGame: buildDataScienceMiniGame(spec),
      knowledgeCheck: mcq(
        spec.mcqQuestion,
        spec.mcqCorrect,
        spec.mcqExpl,
        spec.mcqWrong[0] ?? "Option A",
        "Incorrect option.",
        spec.mcqWrong[1] ?? "Option B",
        "Incorrect option.",
        spec.mcqWrong[2] ?? "Option C",
        "Incorrect option.",
      ),
      realWorldExample: realWorld(spec.realScenario, spec.realApp, "Data Science & Advanced Analytics"),
      projectConfig,
    });
  }

  return curriculum;
}

export const DATASCIENCE_CURRICULUM = buildDataScienceCurriculum();
